import requests
from bs4 import BeautifulSoup
for url in ['https://www.cdc.gov/lice/about/head-lice.html','https://www.cdc.gov/lice/about/head-lice-schools.html']:
    try:
        response=requests.get(url,timeout=20)
        soup=BeautifulSoup(response.text,'html.parser')
        text=' '.join(soup.stripped_strings)
        print('URL',url,'STATUS',response.status_code)
        for term in ['school','head-to-head','nits','classroom','return']:
            pos=text.lower().find(term)
            if pos>=0:
                print(term, text[max(0,pos-250):pos+600])
    except Exception as error:
        print('ERROR',repr(error))
